CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_batch_with_consumption(p_beer_name text, p_planned_brew_date date, p_expected_delivery_date date, p_volume_bbl numeric, p_turns integer, p_status text, p_notes text, p_recipe_id uuid)
 RETURNS brew_batches
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_batch public.brew_batches;
BEGIN
  INSERT INTO public.brew_batches(
    beer_name, planned_brew_date, expected_delivery_date,
    volume_bbl, turns, status, notes, recipe_id
  ) VALUES (
    p_beer_name, p_planned_brew_date, p_expected_delivery_date,
    p_volume_bbl, COALESCE(p_turns, 1), COALESCE(p_status, 'planning'), p_notes, p_recipe_id
  ) RETURNING * INTO v_batch;

  INSERT INTO public.batch_status_history(batch_id, status, note)
    VALUES (v_batch.id, v_batch.status, 'Batch created');

  -- Ingredient deduction happens at turn start (brewhouse assignment), not here.

  RETURN v_batch;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_batch_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.batch_number is null or new.batch_number = '' then
    new.batch_number := 'B-' || lpad(nextval('brew_batch_number_seq')::text, 3, '0');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_batch_transfer(p_batch_id uuid, p_from_tank_id uuid, p_to_tank_id uuid, p_volume_bbl numeric, p_shrinkage_bbl numeric DEFAULT 0, p_transfer_type text DEFAULT 'transfer'::text, p_notes text DEFAULT NULL::text, p_kegging_detail jsonb DEFAULT NULL::jsonb, p_canning_detail jsonb DEFAULT NULL::jsonb)
 RETURNS batch_transfers
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_transfer      public.batch_transfers;
  v_dest_type     text;
  v_new_status    text;
  v_cur_status    text;
  v_unconstrained text[] := ARRAY['kegging','canning','cold_storage','backlog','loading_bay','export_bay'];
  v_incoming_recipe_id uuid;
  v_conflicting_recipe boolean;
BEGIN
  INSERT INTO public.batch_transfers(
    batch_id, from_tank_id, to_tank_id, volume_bbl, shrinkage_bbl,
    transfer_type, notes, kegging_detail, canning_detail
  ) VALUES (
    p_batch_id, p_from_tank_id, p_to_tank_id, p_volume_bbl, COALESCE(p_shrinkage_bbl, 0),
    COALESCE(p_transfer_type, 'transfer'), p_notes, p_kegging_detail, p_canning_detail
  ) RETURNING * INTO v_transfer;

  -- Release the batch's currently-active assignment, if any.
  UPDATE public.batch_tank_assignments
     SET released_at = now()
   WHERE batch_id = p_batch_id AND released_at IS NULL;

  IF p_to_tank_id IS NOT NULL THEN
    SELECT type INTO v_dest_type FROM public.equipment WHERE id = p_to_tank_id;

    IF v_dest_type IS NOT NULL THEN
      v_new_status := CASE v_dest_type
        WHEN 'brewhouse'    THEN 'brewing'
        WHEN 'fermenter'    THEN 'fermenting'
        WHEN 'brite'        THEN 'conditioning'
        WHEN 'kegging'      THEN 'packaging'
        WHEN 'canning'      THEN 'packaging'
        WHEN 'cold_storage' THEN 'archived'
        ELSE NULL
      END;

      -- Only capacity-constrained destinations hold an assignment.
      IF NOT (v_dest_type = ANY(v_unconstrained)) THEN
        -- Same-recipe batches may combine in the same tank. Any existing
        -- occupant with a DIFFERENT recipe still blocks the transfer.
        SELECT recipe_id INTO v_incoming_recipe_id FROM public.brew_batches WHERE id = p_batch_id;

        SELECT EXISTS (
          SELECT 1
          FROM public.batch_tank_assignments a
          JOIN public.brew_batches b ON b.id = a.batch_id
          WHERE a.tank_id = p_to_tank_id
            AND a.released_at IS NULL
            AND a.batch_id <> p_batch_id
            AND (v_incoming_recipe_id IS NULL OR b.recipe_id IS DISTINCT FROM v_incoming_recipe_id)
        ) INTO v_conflicting_recipe;

        IF v_conflicting_recipe THEN
          RAISE EXCEPTION 'Destination tank is already occupied';
        END IF;

        IF NOT EXISTS (
          SELECT 1 FROM public.batch_tank_assignments
           WHERE tank_id = p_to_tank_id AND batch_id = p_batch_id AND released_at IS NULL
        ) THEN
          INSERT INTO public.batch_tank_assignments(batch_id, tank_id, notes)
            VALUES (p_batch_id, p_to_tank_id, NULL);
        END IF;
      END IF;

      IF v_new_status IS NOT NULL THEN
        SELECT status INTO v_cur_status FROM public.brew_batches WHERE id = p_batch_id;
        IF v_cur_status IS DISTINCT FROM v_new_status THEN
          UPDATE public.brew_batches SET status = v_new_status WHERE id = p_batch_id;
          INSERT INTO public.batch_status_history(batch_id, status, note)
            VALUES (p_batch_id, v_new_status, 'Auto: transferred to ' || COALESCE(p_transfer_type, 'transfer'));
        END IF;
      END IF;
    END IF;
  END IF;

  RETURN v_transfer;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_batch_transfer(p_batch_id uuid, p_from_tank_id uuid, p_to_tank_id uuid, p_volume_bbl numeric, p_shrinkage_bbl numeric DEFAULT 0, p_transfer_type text DEFAULT 'transfer'::text, p_notes text DEFAULT NULL::text, p_kegging_detail jsonb DEFAULT NULL::jsonb, p_canning_detail jsonb DEFAULT NULL::jsonb, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS batch_transfers
 LANGUAGE plpgsql
AS $function$
declare
  v_transfer      public.batch_transfers;
  v_dest_type     text;
  v_new_status    text;
  v_cur_status    text;
  v_unconstrained text[] := array['kegging','canning','cold_storage','backlog','loading_bay','export_bay'];
begin
  insert into public.batch_transfers(
    batch_id, from_tank_id, to_tank_id, volume_bbl, shrinkage_bbl,
    transfer_type, notes, kegging_detail, canning_detail, created_by
  ) values (
    p_batch_id, p_from_tank_id, p_to_tank_id, p_volume_bbl, coalesce(p_shrinkage_bbl, 0),
    coalesce(p_transfer_type, 'transfer'), p_notes, p_kegging_detail, p_canning_detail,
    p_created_by
  ) returning * into v_transfer;

  update public.batch_tank_assignments
     set released_at = now()
   where batch_id = p_batch_id and released_at is null;

  if p_to_tank_id is not null then
    select type into v_dest_type from public.equipment where id = p_to_tank_id;
    if v_dest_type is not null then
      v_new_status := case v_dest_type
        when 'brewhouse'    then 'brewing'
        when 'fermenter'    then 'fermenting'
        when 'brite'        then 'conditioning'
        when 'kegging'      then 'packaging'
        when 'canning'      then 'packaging'
        else null
      end;
      if not (v_dest_type = any(v_unconstrained)) then
        if exists (select 1 from public.batch_tank_assignments where tank_id = p_to_tank_id and released_at is null) then
          raise exception 'Destination tank is already occupied';
        end if;
        insert into public.batch_tank_assignments(batch_id, tank_id, notes)
          values (p_batch_id, p_to_tank_id, null);
      end if;
      if v_new_status is not null then
        select status into v_cur_status from public.brew_batches where id = p_batch_id;
        if v_cur_status is distinct from v_new_status then
          update public.brew_batches set status = v_new_status where id = p_batch_id;
          insert into public.batch_status_history(batch_id, status, note)
            values (p_batch_id, v_new_status, 'Auto: transferred to ' || coalesce(p_transfer_type, 'transfer'));
        end if;
      end if;
    end if;
  end if;

  return v_transfer;
end;
$function$
